function calculateTotal(price: number) {
  const tax = price * 0.0825;
  const shipping = price > 50 ? 0 : 5;
  return price + tax + shipping;
}

console.log(calculateTotal(100));

function shouldSendReminder(dayOfMonth: number) {
  // send reminder on the last day of the month
  return dayOfMonth === 31;
}

console.log(shouldSendReminder(31));

